#include "streamforge/broker/broker_service.hpp"
#include "streamforge/benchmark/benchmark.hpp"
#include <algorithm>
#include <chrono>
#include <filesystem>
#include <iostream>
#include <numeric>
#include <vector>
int main(int argc, char** argv) { try { const auto o=streamforge::benchmark::parse_options(argc,argv); if(o.mode=="synced") throw std::invalid_argument("synced mode is unavailable on Windows"); std::cout << "benchmark=local_append build_type=" << STREAMFORGE_BUILD_TYPE << " compiler=" << STREAMFORGE_COMPILER << " os=" << STREAMFORGE_OS << " cpu_usage=not_measured memory_usage=not_measured storage=not_measured\n"; std::vector<double> rates, latencies; std::size_t successful=0;
  for(std::size_t run=0;run<o.repetitions;++run) { streamforge::broker::BrokerService broker(std::filesystem::path(o.data_directory)/("run-"+std::to_string(run))); broker.recover(); broker.create_topic("benchmark",1); const std::vector<std::byte> value(o.payload_bytes); auto append=[&](std::size_t n,bool measure){ std::vector<streamforge::storage::Record> batch(n); for(auto& r:batch) r.value=value; const auto before=std::chrono::steady_clock::now(); (void)broker.produce("benchmark",0,std::move(batch),streamforge::storage::AcknowledgementMode::kAppended); if(measure) latencies.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-before).count()); }; for(std::size_t i=0;i<o.warmup_batches;++i) append(o.batch_size,false); const auto start=std::chrono::steady_clock::now(); std::size_t done=0; while(done<o.messages) { const auto n=std::min(o.batch_size,o.messages-done); append(n,true); done+=n; } const auto seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count(); const auto rate=done/seconds; rates.push_back(rate); successful+=done; std::cout << "run=" << run+1 << " successful_messages=" << done << " elapsed_seconds=" << seconds << " messages_per_second=" << rate << " mib_per_second=" << rate*o.payload_bytes/(1024.0*1024.0) << '\n'; }
  const auto s=streamforge::benchmark::summarize(latencies); const auto median=streamforge::benchmark::percentile(rates,.50); std::cout << "aggregate successful_messages=" << successful << " messages=" << o.messages << " payload_bytes=" << o.payload_bytes << " batch_size=" << o.batch_size << " clients=1 persistence_mode=" << o.mode << " timing=broker_produce_including_record_encoding_file_stream_flush_excluding_tcp p50_batch_ms=" << s.p50_ms << " p95_batch_ms=" << s.p95_ms << " p99_batch_ms=" << s.p99_ms << " median_messages_per_second=" << median << " median_mib_per_second=" << median*o.payload_bytes/(1024.0*1024.0) << '\n'; return 0;
 } catch(const std::exception& e) { std::cerr << "benchmark error: " << e.what() << "\nUsage: eventstream_benchmark <data-directory> [--messages N] [--payload-bytes N] [--batch-size N] [--warmup-batches N] [--repetitions N] [--mode appended|synced]\n"; return 2; } }
